#[cfg(test)]
mod historical_search_oracle {
    use super::*;

    #[test]
    fn long_matching_line_is_bounded() {
        let workspace = tempfile::tempdir().unwrap();
        fs::write(workspace.path().join("input.txt"), format!("MARK{}\n", "x".repeat(16_000))).unwrap();
        let root = fs::canonicalize(workspace.path()).unwrap();
        let result = repository_search_v1(&root, &json!({"path":".", "pattern":"MARK", "maxResults":500})).unwrap();
        let match_result = &result["structuredContent"]["matches"][0];
        assert_eq!(match_result["lineTruncated"], true);
        assert!(match_result["text"].as_str().unwrap().len() <= 4 * 1024);
    }

    #[test]
    fn total_rendered_matches_are_bounded() {
        let workspace = tempfile::tempdir().unwrap();
        let line = format!("MARK{}\n", "x".repeat(4_000));
        fs::write(workspace.path().join("input.txt"), line.repeat(200)).unwrap();
        let root = fs::canonicalize(workspace.path()).unwrap();
        let result = repository_search_v1(&root, &json!({"path":".", "pattern":"MARK", "maxResults":500})).unwrap();
        assert!(result["content"][0]["text"].as_str().unwrap().len() <= 512 * 1024);
        assert_eq!(result["structuredContent"]["truncated"], true);
    }
}

fn collect_regular_files_v1(
    workspace: &Path,
    start: &Path,
    files: &mut Vec<PathBuf>,
) -> Result<()> {
    if files.len() >= MAX_REPOSITORY_ENTRIES_V1 {
        bail!("repository entry bound exceeded");
    }
    let metadata = fs::symlink_metadata(start)?;
    if metadata.file_type().is_symlink() {
        bail!("repository search refuses symlinks");
    }
    if metadata.is_file() {
        files.push(start.to_path_buf());
        return Ok(());
    }
    if !metadata.is_dir() {
        bail!("repository search refuses special files");
    }
    let mut children = fs::read_dir(start)?.collect::<Result<Vec<_>, _>>()?;
    children.sort_by_key(|entry| entry.file_name());
    for child in children {
        let path = child.path();
        if !path.starts_with(workspace) {
            bail!("repository search escaped workspace");
        }
        collect_regular_files_v1(workspace, &path, files)?;
    }
    Ok(())
}

fn argument_path_v1(arguments: &Value, default_dot: bool) -> Result<PathBuf> {
    let object = arguments
        .as_object()
        .ok_or_else(|| anyhow!("arguments must be an object"))?;
    let path = object
        .get("path")
        .and_then(Value::as_str)
        .or(default_dot.then_some("."))
        .ok_or_else(|| anyhow!("path is required"))?;
    if path.is_empty() || path.len() > 4096 || path.as_bytes().contains(&0) {
        bail!("path is invalid");
    }
    let path = PathBuf::from(path);
    if path.is_absolute()
        || path.components().any(|component| {
            matches!(
                component,
                Component::ParentDir | Component::RootDir | Component::Prefix(_)
            )
        })
    {
        bail!("path must be relative and traversal-free");
    }
    Ok(path)
}

